double exahype::limiting::swe::fvSWE::solveRiemannProblem(
  [[maybe_unused]] const double* __restrict__                    QR, // QR[3+1]
  [[maybe_unused]] const double* __restrict__                    QL, // QL[3+1]
  [[maybe_unused]] const double* __restrict__                    FR, // FR[3]
  [[maybe_unused]] const double* __restrict__                    FL, // FL[3]
  [[maybe_unused]] const double* __restrict__                    LR, // LR[3]
  [[maybe_unused]] const double* __restrict__                    LL, // LL[3]
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&  xR,
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&  xL,
  [[maybe_unused]] const tarch::la::Vector<Dimensions, double>&  dx,
  [[maybe_unused]] double                                        t,
  [[maybe_unused]] double                                        dt,
  [[maybe_unused]] int                                           normal,
  [[maybe_unused]] double* __restrict__                          APDQ, // APDQ[3]
  [[maybe_unused]] double* __restrict__                          AMDQ // AMDQ[3]
) {

  if(t>0. && dt<=1e-20){
    ::tarch::triggerNonCriticalAssertion( __FILE__, __LINE__, "_dt>=0", "invalid dt: " + std::to_string(dt) );
  }

  double smax = 0.0;
  for (int i = 0; i < NumberOfUnknowns; i++) {
    const double abs_sL_i = std::abs(LL[i]);
    smax = std::max( abs_sL_i, smax );
  }
  for (int i = 0; i < NumberOfUnknowns; i++) {
    const double abs_sR_i = std::abs(LR[i]);
    smax = std::max( abs_sR_i, smax );
  }

  // double flux[NumberOfUnknowns] = {0.0};

  double HL = std::max(0., QL[0]);
  double HR = std::max(0., QR[0]);

  double hRoe = 0.5*(HL + HR);

  double bm   = std::max(QL[3], QR[3]);
  double Deta = std::max(HR+QR[3] - bm, 0.0) - std::max(HL+QL[3] - bm, 0.0);

  AMDQ[0] = 0.5 * (FL[0] + FR[0]) - 0.5 * smax *  Deta;
  AMDQ[1] = 0.5 * (FL[1] + FR[1]) - 0.5 * smax * (QR[1] - QL[1]);
  AMDQ[2] = 0.5 * (FL[2] + FR[2]) - 0.5 * smax * (QR[2] - QL[2]);

  std::copy_n(AMDQ, NumberOfUnknowns, APDQ);

  AMDQ[normal + 1] += 0.5*9.81*hRoe*Deta;
  APDQ[normal + 1] -= 0.5*9.81*hRoe*Deta;
  
  return smax;

}